import { useTranslation } from 'react-i18next';
import React from 'react';
import LegalDocumentScreen from './LegalDocumentScreen';
import { TERMS_DOCUMENT } from './termsContent.generated';
import { localizedLegalDocument } from './localizedLegalDocument';

// The text is docs/legal/terms-of-service.md, generated by
// scripts/generate-legal-app-content.mjs: the Terms a person accepts in the app are
// the Terms the website serves.
const TermsOfServiceScreen = ({ navigation }: { navigation: { goBack: () => void } }) => {
    const { t, i18n } = useTranslation();
    return (
        <LegalDocumentScreen navigation={navigation} headerTitle={t('legal.terms')} document={localizedLegalDocument(TERMS_DOCUMENT, 'terms', i18n.language)} />
    );
};

export default TermsOfServiceScreen;
